/**
 * Schema validation and sanitization for reasoning trace content.
 *
 * A trace is generated by an LLM-driven agent that ingests headlines, social posts,
 * and arbitrary web pages. Sources can carry malicious payloads, javascript: URLs,
 * Unicode bidi-override characters, or oversized strings.
 *
 * This module enforces strict size limits, strips dangerous control and bidi characters,
 * verifies URL safety, validates known fields against a versioned schema, and isolates
 * unknown fields as inert data.
 */

export const MAX_TRACE_STRING_LENGTH = 15_000;
export const MAX_SIGNAL_STRING_LENGTH = 1_000;
export const MAX_NAME_STRING_LENGTH = 200;
export const MAX_SOURCES_COUNT = 100;
export const MAX_CONDITIONS_COUNT = 50;
export const MAX_TOTAL_SERIALIZED_BYTES = 1024 * 1024; // 1 MB

/**
 * Unicode directional formatting characters (bidi overrides) can invert reading order
 * or disguise dangerous file extensions and URLs.
 * Matches U+200E, U+200F, U+202A..U+202E, U+2066..U+2069, U+061C.
 */
const BIDI_REGEX = /[\u200E\u200F\u202A-\u202E\u2066-\u2069\u061C]/g;

/**
 * Control characters excluding standard whitespace (\t, \n, \r).
 */
const CONTROL_CHARS_REGEX = /[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g;

/**
 * Strips dangerous bidi overrides and non-printable control characters,
 * then enforces a max length limit.
 */
export function sanitizeString(val: unknown, maxLength = MAX_TRACE_STRING_LENGTH): string {
  if (val === null || val === undefined) return "";
  const str = String(val);
  const cleaned = str.replace(BIDI_REGEX, "").replace(CONTROL_CHARS_REGEX, "");
  if (cleaned.length <= maxLength) return cleaned;
  return cleaned.slice(0, maxLength) + "…";
}

/**
 * Strictly validates that a URL uses safe protocols: http:, https:, or ipfs:.
 * Explicitly rejects javascript:, data:, vbscript:, file:, etc.
 */
export function sanitizeUrl(url: unknown): string | null {
  if (typeof url !== "string" || !url.trim()) return null;
  const trimmed = url.trim();

  // Explicit check for dangerous scheme prefixes
  const lower = trimmed.toLowerCase();
  if (
    lower.startsWith("javascript:") ||
    lower.startsWith("data:") ||
    lower.startsWith("vbscript:") ||
    lower.startsWith("file:")
  ) {
    return null;
  }

  // Allow ipfs:// URIs
  if (lower.startsWith("ipfs://")) {
    const cleaned = sanitizeString(trimmed, 500);
    return BIDI_REGEX.test(trimmed) ? null : cleaned;
  }

  try {
    const parsed = new URL(trimmed);
    if (parsed.protocol === "https:" || parsed.protocol === "http:") {
      return parsed.toString();
    }
  } catch {
    return null;
  }
  return null;
}

export interface TraceSource {
  name: string;
  weight: number;
  signal: string;
  url?: string | null;
}

export interface ValidatedTraceContent {
  version: number;
  agent?: string;
  action?: string;
  decisionType?: string;
  probabilityEstimate?: number;
  edge?: number;
  confidence?: number;
  confidenceInterval?: { lower: number; upper: number };
  reasoning: string;
  sources: TraceSource[];
  conditions?: string[];
  betFraction?: number;
  betSizeUsdc?: number;
  timestamp?: number | string;
  rawUnknownFields: Record<string, unknown>;
}

export type TraceValidationResult =
  | { ok: true; data: ValidatedTraceContent; warnings: string[] }
  | { ok: false; error: string };

function clampNumber(val: unknown, min: number, max: number): number | undefined {
  if (val === null || val === undefined) return undefined;
  const num = Number(val);
  if (!Number.isFinite(num)) return undefined;
  return Math.min(max, Math.max(min, num));
}

const KNOWN_ROOT_KEYS = new Set([
  "version",
  "schemaVersion",
  "agent",
  "agentType",
  "model",
  "action",
  "decisionType",
  "probability",
  "probabilityEstimate",
  "yesProb",
  "edge",
  "estimate",
  "expectedValue",
  "confidence",
  "confidenceInterval",
  "reasoning",
  "summary",
  "explanation",
  "rationale",
  "sources",
  "sourcesUsed",
  "previewSources",
  "conditions",
  "hedgeConditions",
  "betFraction",
  "betSizeUsdc",
  "timestamp",
  "publishedAt",
  "createdAt",
]);

/**
 * Validates and sanitizes raw trace content against version 1 schema.
 * Treats all unrecognized keys as inert data.
 */
export function validateTraceContent(raw: unknown): TraceValidationResult {
  if (raw === null || raw === undefined) {
    return { ok: false, error: "Trace content is empty" };
  }

  let obj: Record<string, unknown>;
  const warnings: string[] = [];

  if (typeof raw === "string") {
    try {
      const parsed = JSON.parse(raw);
      if (typeof parsed === "object" && parsed !== null) {
        obj = parsed as Record<string, unknown>;
      } else {
        // Plain string trace: wrap safely as plain reasoning
        return {
          ok: true,
          data: {
            version: 1,
            reasoning: sanitizeString(raw),
            sources: [],
            rawUnknownFields: {},
          },
          warnings: ["Content is raw text, not structured JSON"],
        };
      }
    } catch {
      return {
        ok: true,
        data: {
          version: 1,
          reasoning: sanitizeString(raw),
          sources: [],
          rawUnknownFields: {},
        },
        warnings: ["Content is unparsed text"],
      };
    }
  } else if (typeof raw === "object") {
    obj = raw as Record<string, unknown>;
  } else {
    return { ok: false, error: `Invalid trace content type: ${typeof raw}` };
  }

  // Version identification
  const versionNum = typeof obj.version === "number" ? obj.version : typeof obj.schemaVersion === "number" ? obj.schemaVersion : 1;

  // Reasoning / Summary
  const rawReasoning = obj.reasoning ?? obj.summary ?? obj.explanation ?? obj.rationale ?? "";
  const reasoning = sanitizeString(rawReasoning, MAX_TRACE_STRING_LENGTH);

  // Action / Decision
  const rawAction = obj.action ?? obj.decisionType;
  const action = rawAction ? sanitizeString(rawAction, 100) : undefined;
  const decisionType = obj.decisionType ? sanitizeString(obj.decisionType, 100) : action;

  // Agent
  const rawAgent = obj.agent ?? obj.agentType ?? obj.model;
  const agent = rawAgent ? sanitizeString(rawAgent, 100) : undefined;

  // Probability
  let probabilityEstimate: number | undefined;
  const rawProb = obj.probabilityEstimate ?? obj.probability ?? obj.yesProb;
  if (rawProb !== undefined && rawProb !== null) {
    const p = Number(rawProb);
    if (Number.isFinite(p)) {
      // Normalize percentages > 1 to 0..1
      probabilityEstimate = p > 1 && p <= 100 ? p / 100 : clampNumber(p, 0, 1);
    }
  }

  // Edge & Confidence
  const edge = clampNumber(obj.edge ?? obj.estimate ?? obj.expectedValue, -1, 1);
  const confidence = clampNumber(obj.confidence, 0, 1);

  // Confidence Interval
  let confidenceInterval: { lower: number; upper: number } | undefined;
  if (typeof obj.confidenceInterval === "object" && obj.confidenceInterval !== null) {
    const ci = obj.confidenceInterval as Record<string, unknown>;
    const lower = Number(ci.lower);
    const upper = Number(ci.upper);
    if (Number.isFinite(lower) && Number.isFinite(upper)) {
      confidenceInterval = {
        lower: lower > 1 && lower <= 100 ? lower / 100 : Math.max(0, lower),
        upper: upper > 1 && upper <= 100 ? upper / 100 : Math.min(1, upper),
      };
    }
  }

  // Sources
  const sources: TraceSource[] = [];
  const rawSources = obj.sources ?? obj.sourcesUsed ?? obj.previewSources;
  if (Array.isArray(rawSources)) {
    const sliced = rawSources.slice(0, MAX_SOURCES_COUNT);
    if (rawSources.length > MAX_SOURCES_COUNT) {
      warnings.push(`Sources list capped at ${MAX_SOURCES_COUNT} items (had ${rawSources.length})`);
    }
    for (const item of sliced) {
      if (typeof item === "object" && item !== null) {
        const s = item as Record<string, unknown>;
        const name = sanitizeString(s.name ?? s.source ?? "Source", MAX_NAME_STRING_LENGTH);
        const weight = clampNumber(s.weight, 0, 1) ?? 0;
        const signal = sanitizeString(s.signal ?? "", MAX_SIGNAL_STRING_LENGTH);
        const url = sanitizeUrl(s.url ?? s.link);
        if (s.url && !url) {
          warnings.push(`Unsafe or invalid URL filtered from source "${name}"`);
        }
        sources.push({ name, weight, signal, url });
      }
    }
  }

  // Conditions
  const conditions: string[] = [];
  const rawConditions = obj.conditions ?? obj.hedgeConditions;
  if (Array.isArray(rawConditions)) {
    const sliced = rawConditions.slice(0, MAX_CONDITIONS_COUNT);
    for (const cond of sliced) {
      if (cond) conditions.push(sanitizeString(cond, 500));
    }
  }

  // Bet sizing
  const betFraction = clampNumber(obj.betFraction, 0, 1);
  const rawBetSize = obj.betSizeUsdc;
  const betSizeUsdc = typeof rawBetSize === "number" && Number.isFinite(rawBetSize) ? Math.max(0, rawBetSize) : undefined;

  // Timestamp
  let timestamp: number | string | undefined;
  const rawTs = obj.timestamp ?? obj.publishedAt ?? obj.createdAt;
  if (typeof rawTs === "number" && Number.isFinite(rawTs)) {
    timestamp = rawTs;
  } else if (typeof rawTs === "string") {
    timestamp = sanitizeString(rawTs, 50);
  }

  // Unknown fields: sanitize safely without dropping
  const rawUnknownFields: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj)) {
    if (!KNOWN_ROOT_KEYS.has(key)) {
      rawUnknownFields[sanitizeString(key, 100)] = sanitizeUnknownValue(value);
    }
  }

  return {
    ok: true,
    data: {
      version: versionNum,
      agent,
      action,
      decisionType,
      probabilityEstimate,
      edge,
      confidence,
      confidenceInterval,
      reasoning,
      sources,
      conditions: conditions.length > 0 ? conditions : undefined,
      betFraction,
      betSizeUsdc,
      timestamp,
      rawUnknownFields,
    },
    warnings,
  };
}

/** Recursively sanitizes unknown nested data to guarantee no executable or bidi content. */
function sanitizeUnknownValue(val: unknown, depth = 0): unknown {
  if (depth > 5) return "[Deeply nested data omitted]";
  if (typeof val === "string") return sanitizeString(val, 2_000);
  if (typeof val === "number" || typeof val === "boolean" || val === null) return val;
  if (Array.isArray(val)) {
    return val.slice(0, 50).map((item) => sanitizeUnknownValue(item, depth + 1));
  }
  if (typeof val === "object") {
    const sanitizedObj: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(val as Record<string, unknown>).slice(0, 50)) {
      sanitizedObj[sanitizeString(k, 100)] = sanitizeUnknownValue(v, depth + 1);
    }
    return sanitizedObj;
  }
  return String(val);
}
